### 2.2 Core Components Implementation

#### 1. RESTful API Endpoint Router (ApiGateway)

```csharp
// Startup.cs
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register services
        services.AddControllers();

        // Register API controllers
        services.AddScoped<IOrderController, OrderController>();
        services.AddScoped<IInventoryController, InventoryController>();
        services.AddScoped<IPaymentController, PaymentController>();

        // Register business services
        services.AddScoped<IOrderService, OrderService>();
        services.AddScoped<IInventoryService, InventoryService>();
        services.AddScoped<IPaymentService, PaymentService>();

        // Register repositories
        services.AddScoped<IOrderRepository, OrderRepository>();
        services.AddScoped<IInventoryRepository, InventoryRepository>();
        services.AddScoped<IPaymentRepository, PaymentRepository>();

        // Register database context
        services.AddDbContext<ApplicationDbContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

        // Register Polly circuit breaker for payment gateway
        services.AddTransient<IPaymentGatewayClient, PaymentGatewayClient>();
        services.AddTransient<ICircuitBreaker, CircuitBreaker>();

        // Register inventory lock manager
        services.AddSingleton<IInventoryLockManager, InventoryLockManager>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();
        app.UseAuthorization();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}
```

```csharp
// OrderController.cs
[ApiController]
[Route("api/[controller]")]
public class OrderController : ControllerBase, IOrderController
{
    private readonly IOrderService _orderService;
    private readonly IInventoryService _inventoryService;
    private readonly IPaymentService _paymentService;

    public OrderController(
        IOrderService orderService,
        IInventoryService inventoryService,
        IPaymentService paymentService)
    {
        _orderService = orderService;
        _inventoryService = inventoryService;
        _paymentService = paymentService;
    }

    [HttpPost("process")]
    public async Task<IActionResult> ProcessOrder([FromBody] CreateOrderRequest request)
    {
        try
        {
            var orderId = await _orderService.CreateOrder(request.OrderItems);

            // Reserve inventory
            await _inventoryService.ReserveInventory(orderId, request.OrderItems);

            // Process payment
            var paymentResult = await _paymentService.ProcessPayment(orderId, request.PaymentDetails);

            if (!paymentResult.Success)
            {
                // Rollback inventory reservation if payment fails
                await _inventoryService.ReleaseInventory(orderId, request.OrderItems);
                return BadRequest(paymentResult.ErrorMessage);
            }

            return Ok(new { OrderId = orderId });
        }
        catch (InventoryInsufficientException ex)
        {
            return StatusCode(400, ex.Message);
        }
        catch (Exception ex)
        {
            return StatusCode(500, ex.Message);
        }
    }
}
```

#### 2. Inventory Reservation Engine

```csharp
// InventoryLockManager.cs
public class InventoryLockManager : IInventoryLockManager, IDisposable
{
    private readonly Dictionary<string, SemaphoreSlim> _locks = new();
    private readonly TimeSpan _lockTimeout = TimeSpan.FromSeconds(30);
    private readonly ILogger<InventoryLockManager> _logger;

    public InventoryLockManager(ILogger<InventoryLockManager> logger)
    {
        _logger = logger;
    }

    public async Task<bool> TryAcquireLockAsync(string productId, int quantity)
    {
        var lockKey = $"product_{productId}_lock";

        // Initialize lock if not exists
        if (!_locks.ContainsKey(lockKey))
        {
            _locks[lockKey] = new SemaphoreSlim(1, 1);
        }

        var semaphore = _locks[lockKey];

        try
        {
            var success = await semaphore.WaitAsync(_lockTimeout);

            if (!success)
            {
                _logger.LogWarning("Failed to acquire lock for product {ProductId} within timeout", productId);
                return false;
            }

            return true;
        }
        catch (OperationCanceledException)
        {
            _logger.LogWarning("Lock acquisition timed out for product {ProductId}", productId);
            return false;
        }
    }

    public void ReleaseLock(string productId)
    {
        var lockKey = $"product_{productId}_lock";

        if (_locks.TryGetValue(lockKey, out var semaphore))
        {
            semaphore.Release();
        }
    }

    public void Dispose()
    {
        foreach (var semaphore in _locks.Values)
        {
            semaphore.Dispose();
        }
        _locks.Clear();
    }
}
```

```csharp
// InventoryService.cs
public class InventoryService : IInventoryService
{
    private readonly IInventoryRepository _inventoryRepository;
    private readonly IInventoryLockManager _lockManager;
    private readonly ILogger<InventoryService> _logger;

    public InventoryService(
        IInventoryRepository inventoryRepository,
        IInventoryLockManager lockManager,
        ILogger<InventoryService> logger)
    {
        _inventoryRepository = inventoryRepository;
        _lockManager = lockManager;
        _logger = logger;
    }

    public async Task ReserveInventory(Guid orderId, IEnumerable<OrderItem> items)
    {
        var reservedItems = new List<OrderItem>();
        var failedItems = new List<OrderItem>();

        foreach (var item in items)
        {
            try
            {
                if (await TryReserveItemAsync(item))
                {
                    reservedItems.Add(item);
                }
                else
                {
                    failedItems.Add(item);
                    throw new InventoryInsufficientException($"Insufficient stock for product {item.ProductId}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to reserve inventory for product {ProductId}", item.ProductId);
                throw;
            }
        }

        // If all reservations succeed, persist to database
        if (failedItems.Count == 0)
        {
            await _inventoryRepository.ReserveInventory(orderId, reservedItems);
        }
        else
        {
            // Release locks for successfully reserved items
            foreach (var item in reservedItems)
            {
                _lockManager.ReleaseLock(item.ProductId);
            }

            throw new InventoryInsufficientException("Failed to reserve inventory for some items");
        }
    }

    public async Task<bool> TryReserveItemAsync(OrderItem item)
    {
        // Check if we have enough stock
        var currentStock = await _inventoryRepository.GetStockLevel(item.ProductId);
        if (currentStock < item.Quantity)
        {
            return false;
        }

        // Acquire lock
        if (!await _lockManager.TryAcquireLockAsync(item.ProductId, item.Quantity))
        {
            return false;
        }

        // Update stock level (optimistic concurrency)
        var updated = await _inventoryRepository.UpdateStockLevelAsync(
            item.ProductId,
            currentStock - item.Quantity);

        if (!updated)
        {
            _lockManager.ReleaseLock(item.ProductId);
            return false;
        }

        return true;
    }

    public async Task ReleaseInventory(Guid orderId, IEnumerable<OrderItem> items)
    {
        foreach (var item in items)
        {
            _lockManager.ReleaseLock(item.ProductId);
        }

        await _inventoryRepository.ReleaseInventory(orderId, items);
    }
}
```

#### 3. Payment Gateway Integration with Circuit Breaker

```csharp
// PaymentGatewayClient.cs
public class PaymentGatewayClient : IPaymentGatewayClient
{
    private readonly HttpClient _httpClient;
    private readonly ICircuitBreaker _circuitBreaker;
    private readonly ILogger<PaymentGatewayClient> _logger;

    public PaymentGatewayClient(
        HttpClient httpClient,
        ICircuitBreaker circuitBreaker,
        ILogger<PaymentGatewayClient> logger)
    {
        _httpClient = httpClient;
        _circuitBreaker = circuitBreaker;
        _logger = logger;
    }

    public async Task<PaymentResult> ProcessPaymentAsync(PaymentDetails paymentDetails)
    {
        return await _circuitBreaker.ExecuteAsync(async () =>
        {
            try
            {
                var response = await _httpClient.PostAsJsonAsync(
                    "/payments/process",
                    paymentDetails);

                response.EnsureSuccessStatusCode();

                var result = await response.Content.ReadFromJsonAsync<PaymentResult>();
                return result ?? new PaymentResult { Success = false, ErrorMessage = "Unknown error" };
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Payment gateway request failed");
                return new PaymentResult
                {
                    Success = false,
                    ErrorMessage = "Payment gateway unavailable"
                };
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Payment processing error");
                return new PaymentResult
                {
                    Success = false,
                    ErrorMessage = "Payment processing failed"
                };
            }
        });
    }
}
```

```csharp
// CircuitBreaker.cs
public class CircuitBreaker : ICircuitBreaker
{
    private readonly IResiliencePipeline _pipeline;
    private readonly ILogger<CircuitBreaker> _logger;

    public CircuitBreaker(IResiliencePipeline pipeline, ILogger<CircuitBreaker> logger)
    {
        _pipeline = pipeline;
        _logger = logger;
    }

    public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
    {
        try
        {
            return await _pipeline.ExecuteAsync(action);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Circuit breaker failed");
            throw;
        }
    }
}
```

```csharp
// PaymentService.cs
public class PaymentService : IPaymentService
{
    private readonly IPaymentRepository _paymentRepository;
    private readonly IPaymentGatewayClient _paymentGatewayClient;
    private readonly ILogger<PaymentService> _logger;

    public PaymentService(
        IPaymentRepository paymentRepository,
        IPaymentGatewayClient paymentGatewayClient,
        ILogger<PaymentService> logger)
    {
        _paymentRepository = paymentRepository;
        _paymentGatewayClient = paymentGatewayClient;
        _logger = logger;
    }

    public async Task<PaymentResult> ProcessPayment(Guid orderId, PaymentDetails paymentDetails)
    {
        try
        {
            // First attempt with payment gateway
            var result = await _paymentGatewayClient.ProcessPaymentAsync(paymentDetails);

            if (result.Success)
            {
                // Record successful payment
                await _paymentRepository.RecordPayment(orderId, result.PaymentId, result.Amount);
                return result;
            }

            // If first attempt fails, try fallback mechanism
            if (result.ErrorMessage.Contains("gateway unavailable"))
            {
                _logger.LogWarning("Payment gateway unavailable, attempting fallback");
                result = await FallbackPaymentProcessing(orderId, paymentDetails);
            }

            return result;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Payment processing failed for order {OrderId}", orderId);
            return new PaymentResult
            {
                Success = false,
                ErrorMessage = "Payment processing failed"
            };
        }
    }

    private async Task<PaymentResult> FallbackPaymentProcessing(Guid orderId, PaymentDetails paymentDetails)
    {
        // Implement fallback payment processing logic
        // This could be internal payment processing or retry with different gateway
        return new PaymentResult
        {
            Success = false,
            ErrorMessage = "Fallback payment processing not implemented"
        };
    }
}
```

